  exhausted:{label:'Spent',description:'Squeezed eyes, an open mouth and a hanging tongue.',context:'User reports all-out effort · a moment to pause',left:'M34 34 Q47 38 59 45 Q45 43 35 51',right:'M184 38 Q170 42 158 49 Q172 47 183 55',stroke:2.8,mouth:'M65 91 C62 62 87 56 110 59 C140 56 159 71 157 94 C154 110 140 101 126 93 C107 85 82 115 65 91Z',tongue:0,droop:1,sweat:1,core:'#dc7764',edge:'#e9a282',soft:'#f3d3b7'},
